Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Local Abbreviation SEGS := Plain.M.loaded_segments.

Section Segs3G.
Context {fx : FPState}.
Variable rom : word -> option byte.
#[local] Notation "'u'" := bv_unsigned (only parsing).

(* [comment removed for export] *)
Ltac stepSWe F D aa oktac :=
  chain_step;
  [ reflexivity
  | eapply step_sw_at with (a := aa); [ exact F | reflexivity | exact D | gres; imm_norm; addr_tac | gres; reflexivity | oktac ]
  | step_simpl ].
Ltac fixv' v tac := lazymatch goal with |- msteps _ (mkst (regupd _ _ ?x) _ _ _) _ => first [ constr_eq x v | replace x with v by (symmetry; tac) ] end.


Ltac condM :=
  pin; rewrite ?c_ltu_Z by lia; rewrite ?c_lts_Z by lia; rewrite ?c_eq_Zm; rewrite ?mod32_mod64, ?Zmod_0_l;
  first [ apply Z.ltb_lt | apply Z.ltb_ge | apply Z.eqb_eq | apply Z.eqb_neq | reflexivity ]; rewrite ?Z.mod_small by lia; lia.

Ltac rgF_tail3 bd vd Rd Ed SOK n ps pd s4 d4 :=
  stepLD F_7b09c D_7b09c bd vd ltac:(addr_norm; rewrite ?Z.add_0_r; exact Rd) ltac:(exact Ed);
  sn F_7b0a0 D_7b0a0;
  sn F_7b0a4 D_7b0a4; fixv' (Z_to_bv 64 (n - 1)) ltac:(rewrite zbv_addiw_small by lia; f_equal; lia);
  sn F_7b0a8 D_7b0a8; fixv' (Z_to_bv 64 (ps + 4 + s4)) ltac:(rewrite zbv_add; reflexivity);
  sn F_7b0ac D_7b0ac; sn F_7b0b0 D_7b0b0; sn F_7b0b4 D_7b0b4;
  stepSWe F_7b0b8 D_7b0b8 (Z_to_bv 64 pd) ltac:(store_ok_peel; exact SOK);
  sn F_7b0bc D_7b0bc; fixv' (Z_to_bv 64 (pd + d4)) ltac:(rewrite zbv_add; reflexivity).

(* [comment removed for export] *)
Lemma rg3_F : forall (f6 f7 last : bool) regs m (ps pd s4 d4 n : Z) (bs0 bs1 bd : list byte) (v0 v1 vd : word),
  (0 <= ps)%Z -> (ps + 8 < 2 ^ 64)%Z -> (0 <= pd < 2 ^ 64)%Z -> (1 <= n < 2 ^ 31)%Z -> (if last then n = 1 else 1 < n)%Z ->
  rdn SEGS m (Z_to_bv 64 ps) 4 = Some bs0 -> bytes_le_to_Z bs0 = bv_unsigned v0 ->
  (f6 = true -> f7 = false -> rdn SEGS m (Z_to_bv 64 (ps + 4)) 4 = Some bs1 /\ bytes_le_to_Z bs1 = bv_unsigned v1) ->
  rdn SEGS m (Z_to_bv 64 pd) 4 = Some bd -> bytes_le_to_Z bd = bv_unsigned vd ->
  store_ok SEGS m (Z_to_bv 64 pd) 4 = true ->
  getr regs 1 = Z_to_bv 64 (ps + 4) -> getr regs 8 = Z_to_bv 64 pd -> getr regs 24 = Z_to_bv 64 n ->
  getr regs 20 = Z_to_bv 64 s4 -> getr regs 21 = Z_to_bv 64 d4 ->
  getr regs 22 = Z_to_bv 64 (if f6 then 1 else 0) -> getr regs 23 = Z_to_bv 64 (if f7 then 1 else 0) ->
  exists regs' (w : word),
    msteps SEGS (mkst regs (0x7b11c : word) m rom)
                (mkst regs' (if last then (0x7b1c8 : word) else (0x7b11c : word)) (wbytes m (Z_to_bv 64 pd) (word_to_le_bytes 4 w)) rom)
    /\ getr regs' 1 = Z_to_bv 64 (ps + 4 + s4) /\ getr regs' 8 = Z_to_bv 64 (pd + d4) /\ getr regs' 24 = Z_to_bv 64 (n - 1)
    /\ regs_agree (fun r => In r [1; 7; 8; 24; 31]%list) regs regs'.
