(* [comment removed for export] *)
Ltac rgL_tail3 bd vd Rd Ed SOK n ps pd s4 d4 :=
  stepLD F_7b198 D_7b198 bd vd ltac:(addr_norm; rewrite ?Z.add_0_r; exact Rd) ltac:(exact Ed);
  sn F_7b19c D_7b19c;
  sn F_7b1a0 D_7b1a0; fixv' (Z_to_bv 64 (n - 1)) ltac:(rewrite zbv_addiw_small by lia; f_equal; lia);
  sn F_7b1a4 D_7b1a4; fixv' (Z_to_bv 64 (ps + 4 + s4)) ltac:(rewrite zbv_add; reflexivity);
  sn F_7b1a8 D_7b1a8; sn F_7b1ac D_7b1ac; sn F_7b1b0 D_7b1b0;
  stepSWe F_7b1b4 D_7b1b4 (Z_to_bv 64 pd) ltac:(store_ok_peel; exact SOK);
  sn F_7b1b8 D_7b1b8; fixv' (Z_to_bv 64 (pd + d4)) ltac:(rewrite zbv_add; reflexivity).

Lemma rg3_L : forall (f last : bool) regs m (ps pd s4 d4 n : Z) (bs0 bs1 bd : list byte) (v0 v1 vd : word),
  (0 <= ps)%Z -> (ps + 8 < 2 ^ 64)%Z -> (0 <= pd < 2 ^ 64)%Z -> (1 <= n < 2 ^ 31)%Z -> (if last then n = 1 else 1 < n)%Z ->
  rdn SEGS m (Z_to_bv 64 ps) 4 = Some bs0 -> bytes_le_to_Z bs0 = bv_unsigned v0 ->
  (f = false -> rdn SEGS m (Z_to_bv 64 (ps + 4)) 4 = Some bs1 /\ bytes_le_to_Z bs1 = bv_unsigned v1) ->
  rdn SEGS m (Z_to_bv 64 pd) 4 = Some bd -> bytes_le_to_Z bd = bv_unsigned vd ->
  store_ok SEGS m (Z_to_bv 64 pd) 4 = true ->
  getr regs 7 = Z_to_bv 64 (ps + 4) -> getr regs 5 = Z_to_bv 64 pd -> getr regs 12 = Z_to_bv 64 n ->
  getr regs 13 = Z_to_bv 64 s4 -> getr regs 14 = Z_to_bv 64 d4 -> getr regs 28 = Z_to_bv 64 (if f then 1 else 0) ->
  exists regs' (w : word),
    msteps SEGS (mkst regs (0x7b218 : word) m rom)
                (mkst regs' (if last then (0x7bf48 : word) else (0x7b218 : word)) (wbytes m (Z_to_bv 64 pd) (word_to_le_bytes 4 w)) rom)
    /\ getr regs' 7 = Z_to_bv 64 (ps + 4 + s4) /\ getr regs' 5 = Z_to_bv 64 (pd + d4) /\ getr regs' 12 = Z_to_bv 64 (n - 1)
