(* [comment removed for export] *)
Lemma rg3_P0 : forall regs m (s DX SX swpl datas : Z),
  (112 <= s)%Z -> (s + 64 < 2 ^ 64)%Z -> (0 <= DX < 2 ^ 31)%Z -> (0 <= SX < 2 ^ 31)%Z -> (DX mod 32 <> SX mod 32)%Z ->
  rdn SEGS m (Z_to_bv 64 (s + 8)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 3)) ->
  rdn SEGS m (Z_to_bv 64 (s + 16)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 datas)) ->
  rdn SEGS m (Z_to_bv 64 (s + 40)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 swpl)) ->
  getr regs 2 = Z_to_bv 64 (s - 112) -> getr regs 19 = Z_to_bv 64 DX -> getr regs 26 = Z_to_bv 64 SX ->
  exists regs',
    msteps SEGS (mkst regs (0x7a0fc : word) m rom) (mkst regs' (0x7a1dc : word) m rom)
    /\ getr regs' 13 = Z_to_bv 64 swpl /\ getr regs' 22 = Z_to_bv 64 datas /\ getr regs' 21 = Z_to_bv 64 2
    /\ getr regs' 20 = Z_to_bv 64 (DX mod 32) /\ getr regs' 30 = Z_to_bv 64 (SX mod 32) /\ getr regs' 15 = Z_to_bv 64 (Z.lor DX SX mod 32)
    /\ regs_agree (fun r => In r [10; 11; 13; 15; 20; 21; 22; 30]%list) regs regs'.
