(* [comment removed for export] *)
Lemma rg3_Q5 : forall (nl : bool) regs m (s DX SX DW dy sy dwpl swpl datad datas nfw srs : Z),
  (112 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= DX < 2 ^ 30)%Z -> (0 <= SX < 2 ^ 30)%Z -> (0 <= DW < 2 ^ 30)%Z -> (g_hang DX <= DW)%Z ->
  (0 <= nfw < 2 ^ 26)%Z -> (0 <= srs <= 32)%Z -> (if nl then g_lwb DX DW = 0 else g_lwb DX DW <> 0)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 112)) 8 = true ->
  getr regs 2 = Z_to_bv 64 (s - 112) -> getr regs 6 = Z_to_bv 64 DW -> getr regs 19 = Z_to_bv 64 DX -> getr regs 31 = Z_to_bv 64 (DW - g_hang DX) ->
  getr regs 30 = Z_to_bv 64 (DX + g_hang DX) -> getr regs 26 = Z_to_bv 64 (SX + g_hang DX) -> getr regs 28 = Z_to_bv 64 nfw ->
  getr regs 27 = Z_to_bv 64 dy -> getr regs 23 = Z_to_bv 64 sy -> getr regs 14 = Z_to_bv 64 dwpl -> getr regs 13 = Z_to_bv 64 swpl ->
  getr regs 5 = Z_to_bv 64 datad -> getr regs 22 = Z_to_bv 64 datas -> getr regs 16 = Z_to_bv 64 srs -> getr regs 21 = Z_to_bv 64 2 ->
  exists regs',
    msteps SEGS (mkst regs (0x7a51c : word) m rom)
                (mkst regs' (0x7a5ac : word) (wbytes m (Z_to_bv 64 (s - 112)) (word_to_le_bytes 8 (Z_to_bv 64 (if nl then 1 else 0)))) rom)
    /\ getr regs' 19 = Z_to_bv 64 (if (DW - g_hang DX <? 32)%Z then 1 else 0)
    /\ (nl = false -> getr regs' 5 = Z_to_bv 64 (datad + 4 * (dy * dwpl) + 4 * ((DX + g_hang DX) / 32) + 4 * nfw)
                   /\ getr regs' 26 = Z_to_bv 64 (datas + 4 * (sy * swpl) + 4 * ((SX + g_hang DX) / 32) + 4 * nfw)
                   /\ getr regs' 30 = Z_to_bv 64 (if (srs <? g_lwb DX DW)%Z then 0 else 1))
    /\ regs_agree (fun r => In r [5; 6; 7; 19; 22; 23; 26; 30; 31]%list) regs regs'.
